insert into public.notas_paroquia (paroquia_id, texto, fontes, confianca) values
  ('4a0c17b3-346e-5714-b312-8d00494ed246', 'Vicariato Soledade (Região Centro). Horários da página geral de missas da arquidiocese (atualizada em 09/2026, sem data por paróquia).', '{"https://www.arquidioceseolindarecife.org/horarios-de-missas/","https://www.arquidioceseolindarecife.org/soledade/","https://www.arquidioceseolindarecife.org/paroquias/recife/"}', 'media'),
  ('17edddae-a156-53ec-8ed2-909b72f5c7cd', 'Vicariato Soledade (Região Centro). Os horários da Capela N. Sra. de Lourdes, da Capela São Joaquim e Sant''Ana e do Rosarinho vêm na página geral logo depois de outra paróquia, mas com o telefone desta. Horários da página geral de missas da arquidiocese (atualizada em 09/2026, sem data por paróquia). Fora do formato: Capela Nossa Senhora dos Aflitos: segunda, quarta e quinta às 16h; domingo às 11h. Capela Nossa Senhora de Lourdes (Hospital dos Servidores): terça às 16h. Capela São Joaquim e Sant''Ana: 1º sábado do mês às 19h30. Praça Nossa Senhora de Fátima, no Rosarinho: 1ª segunda-feira do mês às 19h.', '{"https://www.arquidioceseolindarecife.org/horarios-de-missas/","https://www.arquidioceseolindarecife.org/soledade/","https://www.arquidioceseolindarecife.org/paroquias/recife/"}', 'media'),
  ('5cdf98bb-1338-57bf-93db-dd8b00821459', 'Vicariato Soledade (Região Centro). A matriz é a Basílica da Penha, dos capuchinhos. Horários da página geral de missas da arquidiocese (atualizada em 09/2026, sem data por paróquia). Fora do formato: Bênção de São Félix às sextas-feiras, das 6h às 18h.', '{"https://www.arquidioceseolindarecife.org/horarios-de-missas/","https://www.arquidioceseolindarecife.org/soledade/","https://www.arquidioceseolindarecife.org/paroquias/recife/"}', 'media'),
  ('a2fd1405-f43b-54d8-9f5f-ccd19583ea97', 'Vicariato Soledade (Região Centro). Sem horário: a arquidiocese não publica os horários desta paróquia e o site ou perfil próprio não foi encontrado.', '{"https://www.arquidioceseolindarecife.org/soledade/","https://www.arquidioceseolindarecife.org/paroquias/recife/"}', ''),
