  ('c327894b-aa2b-5ae5-b72c-1b0e446339ec', 'Forania Nossa Senhora das Dores. Criada em 22/11/2018. A tabela de 2025 dava outro endereço (R. Onze, Cedro); ficou o da página da paróquia. Ponto no mapa aproximado: centro da cidade.', '{"https://www.diocesedecaruarupe.com/foraniadasdores"}', 'alta'),
  ('46ed32f0-d9f4-5a7a-872c-048a33b175fe', 'Forania São Francisco de Assis. Criada em 04/10/1952. A tabela de 2025 trazia também sábado 17h e quinta 19h30, que a página atual da paróquia não traz. Ponto no mapa aproximado: centro da cidade.', '{"https://www.diocesedecaruarupe.com/foraniasaofrancisco"}', 'alta'),
  ('b30407e5-bf56-55ab-a3ef-2dff48ff94e2', 'Forania São Francisco de Assis. Criada em 08/12/1965. A tabela de 2025 trazia também sábado 17h e primeira sexta 17h, que a página atual da paróquia não traz.', '{"https://www.diocesedecaruarupe.com/foraniasaofrancisco"}', 'alta'),
  ('9ac5cba1-87fb-5fb7-a768-0010c26de275', 'Forania São Francisco de Assis. Criada em 12/04/2015. Fora do formato: Comunidades sem bairro na fonte: Santa Rosa (quarta 19h30, domingo 17h); Conferência Vicentina (domingo 7h, 1ª sexta 17h, 4ª terça 17h); Frei Galvão (2º sábado 17h); São José (3º sábado 17h); N. S. Aparecida (4º sábado 17h).', '{"https://www.diocesedecaruarupe.com/foraniasaofrancisco"}', 'alta'),
