  ('2fdc2867-0cb5-5569-93bc-a390eb3496d4', 'Região Pastoral Belo Jardim. Página da unidade no site da diocese, atualizada em 2026-08-11. Criada em 2001. Outro telefone publicado: (81) 99121-2882.', '{"https://diocesedepesqueira.com.br/paroquia/paroquia-nossa-senhora-da-saude/","https://diocesedepesqueira.com.br/paroquia/paroquia-nossa-senhora-da-saude/"}', 'alta'),
