  ('a49ca899-5b0d-5f3f-980a-63507898d178', 'Forania São Marcos. Fora do formato: Dia 4 de cada mês: missa votiva ao padroeiro às 19h30. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-sao-francisco-de-assis-salgueiro/","https://diocesedesalgueiro.org.br/paroquia/paroquia-sao-francisco-de-assis-salgueiro/"}', 'alta'),
  ('7c7efe7a-40ef-5e83-a3b3-e4dc24ec3370', 'Forania São Marcos. Fora do formato: Dia 14 de cada mês: missa às 12h. Atendimento com o padre: quarta, 14h às 17h, e sexta, 8h às 11h. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-santa-cruz-salgueiro/","https://diocesedesalgueiro.org.br/paroquia/paroquia-santa-cruz-salgueiro/"}', 'alta'),
  ('76345904-d0e3-571a-be8b-dc3d3fa43e09', 'Forania São Marcos. Fora do formato: Dia 20 de cada mês: missa às 6h na Estátua do Pe. Cícero. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-serrita/","https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-serrita/"}', 'alta'),
  ('e39e3128-1b38-5282-87f9-a2e5d578b453', 'Forania São Marcos. A Sagrada Família é a copadroeira; a Igreja da Sagrada Família não tem endereço publicado. Fora do formato: A página não diz em qual igreja são a confissão e a adoração.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-cabrobo/","https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-da-conceicao-cabrobo/"}', 'alta'),
  ('71759316-238d-52d3-bd5f-2b008d1d750e', 'Forania São Marcos.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-do-perpetuo-socorro-cedro/","https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-do-perpetuo-socorro-cedro/"}', 'alta'),
  ('70e612cd-7b96-59e8-b99d-091378ee6899', 'Forania São Marcos.', '{"https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-do-perpetuo-socorro-verdejante/","https://diocesedesalgueiro.org.br/paroquia/paroquia-nossa-senhora-do-perpetuo-socorro-verdejante/"}', 'alta'),
