  ('2ae97480-6952-5dfc-b197-356d73cadf56', 'Forania São Mateus.', '{"https://diocesedesalgueiro.org.br/paroquia/nossa-senhora-das-dores-araripina/","https://diocesedesalgueiro.org.br/paroquia/nossa-senhora-das-dores-araripina/"}', 'alta'),
  ('9d26e687-42f5-5c7b-a2f7-d3aeb682b9fc', 'Forania São Mateus. Também publica o (87) 98142-5441. Fora do formato: Dia 8 de cada mês: missa às 12h.', '{"https://diocesedesalgueiro.org.br/paroquia/imaculada-conceicao-araripina/","https://diocesedesalgueiro.org.br/paroquia/imaculada-conceicao-araripina/"}', 'alta'),
